-- =====================================================================
-- Locale_402.lua — v4.0.2 Astral Forge Studio V2
-- =====================================================================

TomoMod_RegisterLocale("enUS", {
    ["wn_402_astral_dragging"] = "Fixed — Dragging an element in Astral Forge Studio now moves the preview itself instead of turning its selection handle into an independent screen-anchored frame. The handle remains attached to the Studio when the complete window is moved.",
    ["wn_402_astral_handles"] = "Changed — Selection handles now follow the real preview element automatically when the Studio is moved, resized or rescaled. Small elements remain easy to grab without changing their visible geometry, and live snapping and alignment guides continue to use the element's actual position.",
    ["wn_402_astral_instances"] = "New — Instanced Forge elements now use the same selection and drag path as singleton elements. Custom text instances can be selected, outlined and repositioned directly on the canvas, with the same foundation ready for future custom bars.",
    ["wn_402_astral_frame_editor"] = "New — Astral Forge Studio gains a dedicated Frame editor for Player, Target and Nameplate subjects. The Frame button switches from individual element positioning to frame-level settings without leaving the Studio.",
    ["wn_402_astral_frame_controls"] = "New — Adjust frame dimensions and core display directly: health, power, information and cast-bar sizes; name size; names, levels and health text; health format; classification, cast bars, class colours, absorbs and threat where supported by the selected subject.",
    ["wn_402_astral_frame_live"] = "Changed — Frame edits use the normal TomoMod profile and refresh paths, updating the preview and game frames immediately. A dedicated reset restores supported frame fields to their defaults, while Refresh Preview remains available separately.",
    ["wn_402_astral_custom_bars"] = "New — Create up to eight independent custom bars on Player and Target frames and up to six on Nameplates. Every bar is a normal Forge element that can be selected, dragged and anchored directly in the preview.",
    ["wn_402_astral_bar_sources"] = "New — Custom bars can follow live Health, live Power on unit frames, or a static decorative fill. Width, height, colour mode, custom colour, background opacity and reverse fill are configured independently for every bar.",
    ["wn_402_astral_bar_runtime"] = "Changed — UnitFrame bars receive the game's secret-safe health and power values directly, while Nameplate bars update with their unit and are cleared when a pooled plate is released so visuals cannot leak between units.",
    ["wn_402_astral_navigation"] = "New — Frame, Elements, Bars and Presets are now dedicated navigation tabs above the canvas, with a clear active state and synchronised selection when the subject or edited element changes.",
    ["wn_402_astral_onboarding"] = "New — A localized six-step first-run guide introduces subject selection, frame editing, canvas movement, custom bars and presets. Progress is versioned, and the Help button can restart the guide at any time.",
    ["wn_402_astral_localization"] = "Changed — The Studio shell, navigation, subject selector, sidebar, refresh and reset actions, placement hint and empty-selection guidance are now fully translated in all six supported languages.",
    ["wn_402_bags_visuals"] = "Changed — Bags V4 now uses a lighter cool-grey panel and recessed slots. Item quality uses a restrained tint by default, with Tinted Slot, Coloured Frame, Both and None available in settings; reagent-bag slots retain their azure outline.",
    ["wn_402_bags_rendering"] = "Fixed — Occupied bag slots now draw their own icon and count instead of depending on Blizzard template regions that changed on the current client. Real items no longer look like empty slots, while secure clicks, tooltips and cooldowns remain native.",
    ["wn_402_chat_community_filters"] = "New — Right-click the Community tab to choose independently between character whispers, Battle.net whispers, Guild chat and Officer chat. The dedicated filter menu is localized and refreshes the combined view immediately.",
    ["wn_402_chat_community_capture"] = "Fixed — Community now captures supported chat events directly and keeps a short replay history, so Guild and Officer messages remain complete even when Blizzard does not route them through a detected chat window. The synthetic tab no longer forwards right-clicks to a native tab, preventing the protected chat-filter taint path.",
    ["wn_402_quiet_startup"] = "Changed — Successful initialization notices from SkyRide, HideCastBar, UnitFrames, Boss Frames and Nameplates no longer fill the chat window at login. Error, lock-state and combat warnings remain available.",
    ["wn_402_import_named_selective"] = "New — Selective import now works when creating a named profile as well as when updating the active configuration. Choose the modules to apply, then TomoMod saves and activates the resulting configuration under the requested profile name.",
    ["wn_402_import_destination_feedback"] = "Changed — The import selector now shows whether its destination is the active configuration or a new named profile. Successful saves and selector failures provide clear localized feedback, including when an import string contains no recognised module.",
    ["wn_402_import_paste_absorber"] = "Fixed — Pasting very large export strings no longer freezes the import box while it lays out thousands of characters. The complete paste stays in a lightweight Lua buffer while the box shows a localized character count, with a safe retry instead of silent truncation when the client cannot deliver the full paste.",
    ["wn_402_import_decode_cache"] = "Changed — Selective import now reuses the payload already decoded for the preview, avoiding a second decode, decompression and deserialization pass immediately before module selection.",
    ["wn_402_import_layering"] = "Fixed — The selective-import panel recalculates its display level whenever it opens and raises both its backdrop and content above the current TomoMod configuration window, so a reused selector can no longer remain hidden behind it.",
    ["wn_402_import_theme"] = "Changed — The selector now uses the shared TomoMod theme, Poppins fonts, inset content surface, slim scrollbar, custom checkboxes and themed buttons. Native Blizzard panel templates and hard-coded accent colours have been removed from its normal presentation.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_402_astral_dragging"] = "Correction — Faire glisser un élément dans Astral Forge Studio déplace désormais l'aperçu lui-même au lieu de transformer sa poignée de sélection en cadre indépendant ancré à l'écran. La poignée reste attachée au Studio lorsque la fenêtre complète est déplacée.",
    ["wn_402_astral_handles"] = "Modification — Les poignées de sélection suivent maintenant automatiquement l'élément réel de l'aperçu lorsque le Studio est déplacé, redimensionné ou mis à l'échelle. Les petits éléments restent faciles à saisir sans modifier leur géométrie visible, et l'alignement magnétique ainsi que les guides utilisent toujours leur position réelle.",
    ["wn_402_astral_instances"] = "Nouveauté — Les éléments Forge instanciés utilisent désormais le même système de sélection et de déplacement que les éléments uniques. Les textes personnalisés peuvent être sélectionnés, encadrés et repositionnés directement sur le canevas, avec une base également prête pour de futures barres personnalisées.",
    ["wn_402_astral_frame_editor"] = "Nouveauté — Astral Forge Studio dispose d'un éditeur de cadre dédié aux sujets Joueur, Cible et Plaques de nom. Le bouton Cadre remplace le positionnement des éléments individuels par les réglages du cadre sans quitter le Studio.",
    ["wn_402_astral_frame_controls"] = "Nouveauté — Réglez directement les dimensions et l'affichage principal : tailles des barres de vie, de ressource, d'informations et d'incantation, taille du nom, noms, niveaux et texte de vie, format de vie, classification, barre d'incantation, couleurs de classe, absorptions et menace selon le sujet sélectionné.",
    ["wn_402_astral_frame_live"] = "Modification — Les réglages de cadre utilisent le profil et le système d'actualisation habituels de TomoMod pour mettre immédiatement à jour l'aperçu et les cadres en jeu. Une réinitialisation dédiée restaure les champs compatibles, tandis que l'aperçu peut toujours être rafraîchi séparément.",
    ["wn_402_astral_custom_bars"] = "Nouveauté — Créez jusqu'à huit barres personnalisées indépendantes sur les cadres Joueur et Cible, et jusqu'à six sur les Plaques de nom. Chaque barre est un élément Forge normal qui peut être sélectionné, déplacé et ancré directement dans l'aperçu.",
    ["wn_402_astral_bar_sources"] = "Nouveauté — Les barres personnalisées peuvent suivre la Santé, la Puissance sur les cadres d'unité ou afficher un remplissage décoratif statique. Largeur, hauteur, mode de couleur, couleur personnalisée, opacité du fond et remplissage inversé se règlent séparément pour chaque barre.",
    ["wn_402_astral_bar_runtime"] = "Modification — Les barres des cadres d'unité reçoivent directement les valeurs protégées de santé et de puissance du jeu, tandis que celles des Plaques de nom suivent leur unité et sont effacées lorsqu'une plaque recyclée est libérée afin d'éviter tout transfert visuel.",
    ["wn_402_astral_navigation"] = "Nouveauté — Cadre, Éléments, Barres et Presets disposent maintenant de vrais onglets de navigation au-dessus du canevas, avec un état actif clair et une sélection synchronisée lorsque le sujet ou l'élément change.",
    ["wn_402_astral_onboarding"] = "Nouveauté — Un guide de première utilisation localisé en six étapes présente le choix du sujet, l'édition du cadre, le déplacement sur le canevas, les barres personnalisées et les Presets. La progression est versionnée et le bouton Aide peut relancer le guide à tout moment.",
    ["wn_402_astral_localization"] = "Modification — La fenêtre du Studio, la navigation, le sélecteur de sujet, la barre latérale, les actions d'actualisation et de réinitialisation, l'aide au placement et le message de sélection sont maintenant entièrement traduits dans les six langues prises en charge.",
    ["wn_402_bags_visuals"] = "Modification — Bags V4 utilise désormais un panneau gris froid plus clair et des cases en retrait. La qualité des objets emploie une teinte discrète par défaut, avec les choix Case teintée, Cadre coloré, Les deux et Aucune dans les réglages ; les cases du sac de composants conservent leur contour azur.",
    ["wn_402_bags_rendering"] = "Correction — Les cases occupées dessinent maintenant leur propre icône et leur quantité au lieu de dépendre de régions internes du modèle Blizzard modifiées sur le client actuel. Les objets réels ne ressemblent plus à des cases vides, tandis que les clics sécurisés, les infobulles et les temps de recharge restent natifs.",
    ["wn_402_chat_community_filters"] = "Nouveauté — Un clic droit sur l'onglet Communautaire permet de choisir séparément les messages privés, les messages Battle.net, la guilde et les officiers. Ce menu dédié est traduit et actualise immédiatement la vue regroupée.",
    ["wn_402_chat_community_capture"] = "Correction — L'onglet Communautaire capture directement les événements de chat compatibles et conserve un court historique à rejouer ; les messages de guilde et d'officier restent donc complets même si Blizzard ne les transmet pas à une fenêtre détectée. L'onglet synthétique ne redirige plus les clics droits vers un onglet natif, ce qui évite la source de taint liée aux filtres protégés du chat.",
    ["wn_402_quiet_startup"] = "Modification — Les confirmations d'initialisation de SkyRide, HideCastBar, des cadres d'unité, des cadres de boss et des plaques de nom n'encombrent plus le chat à la connexion. Les erreurs et les avertissements de verrouillage ou de combat restent disponibles.",
    ["wn_402_import_named_selective"] = "Nouveauté — L'import sélectif fonctionne désormais lors de la création d'un profil nommé comme lors de la mise à jour de la configuration active. Choisissez les modules à appliquer, puis TomoMod enregistre et active le résultat sous le nom de profil demandé.",
    ["wn_402_import_destination_feedback"] = "Modification — Le sélecteur d'import indique maintenant si sa destination est la configuration active ou un nouveau profil nommé. Les enregistrements réussis et les échecs du sélecteur donnent un retour clair et traduit, notamment lorsqu'une chaîne d'import ne contient aucun module reconnu.",
    ["wn_402_import_paste_absorber"] = "Correction — Coller une très longue chaîne d'export ne bloque plus la zone d'import pendant l'affichage de milliers de caractères. Le collage complet reste dans un tampon Lua léger tandis que la zone affiche un compteur traduit, avec une nouvelle tentative sûre plutôt qu'une troncature silencieuse si le client ne transmet pas tout le collage.",
    ["wn_402_import_decode_cache"] = "Modification — L'import sélectif réutilise maintenant les données déjà décodées pour l'aperçu, évitant un second décodage, une seconde décompression et une seconde désérialisation juste avant le choix des modules.",
    ["wn_402_import_layering"] = "Correction — Le panneau d'import sélectif recalcule son niveau d'affichage à chaque ouverture et place son fond comme son contenu au-dessus de la fenêtre de configuration TomoMod active ; un sélecteur réutilisé ne peut donc plus rester caché derrière elle.",
    ["wn_402_import_theme"] = "Modification — Le sélecteur utilise désormais le thème commun de TomoMod, les polices Poppins, une surface de contenu en retrait, la barre de défilement fine, des cases personnalisées et des boutons assortis. Les modèles Blizzard et les couleurs d'accent codées en dur ont disparu de son affichage normal.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_402_astral_dragging"] = "Behoben — Beim Ziehen eines Elements in Astral Forge Studio wird jetzt die Vorschau selbst bewegt, statt den Auswahlrahmen in einen unabhängigen, am Bildschirm verankerten Frame zu verwandeln. Der Rahmen bleibt am Studio befestigt, wenn das gesamte Fenster verschoben wird.",
    ["wn_402_astral_handles"] = "Geändert — Auswahlrahmen folgen dem tatsächlichen Vorschauelement jetzt automatisch, wenn das Studio verschoben, skaliert oder in seiner Größe verändert wird. Kleine Elemente bleiben leicht greifbar, ohne ihre sichtbare Geometrie zu verändern, und Einrasten sowie Ausrichtungshilfen verwenden weiterhin ihre tatsächliche Position.",
    ["wn_402_astral_instances"] = "Neu — Instanziierte Forge-Elemente verwenden jetzt dieselbe Auswahl- und Ziehfunktion wie einzelne Elemente. Benutzerdefinierte Textinstanzen können direkt auf der Arbeitsfläche ausgewählt, umrandet und neu positioniert werden; dieselbe Grundlage steht für zukünftige benutzerdefinierte Leisten bereit.",
    ["wn_402_astral_frame_editor"] = "Neu — Astral Forge Studio erhält einen eigenen Rahmen-Editor für Spieler, Ziel und Namensplaketten. Die Schaltfläche Rahmen wechselt von der Positionierung einzelner Elemente zu den Rahmeneinstellungen, ohne das Studio zu verlassen.",
    ["wn_402_astral_frame_controls"] = "Neu — Abmessungen und zentrale Anzeige lassen sich direkt anpassen: Größen von Gesundheits-, Ressourcen-, Info- und Zauberleisten, Namensgröße, Namen, Stufen und Gesundheitstext, Gesundheitsformat, Klassifizierung, Zauberleisten, Klassenfarben, Absorptionen und Bedrohung, soweit vom gewählten Ziel unterstützt.",
    ["wn_402_astral_frame_live"] = "Geändert — Rahmenänderungen verwenden die normalen Profil- und Aktualisierungswege von TomoMod und aktualisieren Vorschau und Spielframes sofort. Eine eigene Zurücksetzung stellt unterstützte Felder auf ihre Standardwerte, während die Vorschau weiterhin separat aktualisiert werden kann.",
    ["wn_402_astral_custom_bars"] = "Neu — Erstelle bis zu acht unabhängige eigene Leisten auf Spieler- und Zielrahmen sowie bis zu sechs auf Namensplaketten. Jede Leiste ist ein normales Forge-Element, das direkt in der Vorschau ausgewählt, verschoben und verankert werden kann.",
    ["wn_402_astral_bar_sources"] = "Neu — Eigene Leisten können live Gesundheit, auf UnitFrames live Ressourcen oder eine statische dekorative Füllung anzeigen. Breite, Höhe, Farbmodus, eigene Farbe, Hintergrunddeckkraft und umgekehrte Füllung werden für jede Leiste getrennt eingestellt.",
    ["wn_402_astral_bar_runtime"] = "Geändert — UnitFrame-Leisten erhalten die geschützten Gesundheits- und Ressourcenwerte des Spiels direkt. Namensplaketten-Leisten folgen ihrer Einheit und werden beim Freigeben einer wiederverwendeten Plakette entfernt, damit keine Anzeige zwischen Einheiten übertragen wird.",
    ["wn_402_astral_navigation"] = "Neu — Rahmen, Elemente, Leisten und Presets sind jetzt eigene Navigationsreiter über dem Canvas, mit klarer Aktivanzeige und synchronisierter Auswahl beim Wechsel des Ziels oder Elements.",
    ["wn_402_astral_onboarding"] = "Neu — Eine lokalisierte Einführung in sechs Schritten erklärt Zielauswahl, Rahmenbearbeitung, Canvas-Bewegung, eigene Leisten und Presets. Der Fortschritt ist versioniert und die Hilfe kann die Einführung jederzeit neu starten.",
    ["wn_402_astral_localization"] = "Geändert — Studiofenster, Navigation, Zielauswahl, Seitenleiste, Aktualisieren und Zurücksetzen, Platzierungshinweis und Auswahlhilfe sind jetzt vollständig in allen sechs unterstützten Sprachen übersetzt.",
    ["wn_402_bags_visuals"] = "Geändert — Bags V4 verwendet jetzt eine hellere, kühlgraue Oberfläche mit vertieften Plätzen. Die Gegenstandsqualität wird standardmäßig dezent eingefärbt; in den Einstellungen stehen Eingefärbter Platz, Farbiger Rahmen, Beides und Nichts zur Wahl. Plätze der Reagenzientasche behalten ihren azurblauen Rand.",
    ["wn_402_bags_rendering"] = "Behoben — Belegte Taschenplätze zeichnen jetzt ihr eigenes Symbol und ihre Anzahl, statt von internen Blizzard-Vorlagenbereichen abzuhängen, die sich im aktuellen Client geändert haben. Echte Gegenstände sehen nicht mehr wie leere Plätze aus; sichere Klicks, Tooltips und Abklingzeiten bleiben nativ.",
    ["wn_402_chat_community_filters"] = "Neu — Ein Rechtsklick auf den Gemeinschaft-Reiter erlaubt die getrennte Auswahl von privaten Nachrichten, Battle.net-Flüstern sowie Gilden- und Offizierschat. Das eigene Menü ist lokalisiert und aktualisiert die Sammelansicht sofort.",
    ["wn_402_chat_community_capture"] = "Behoben — Gemeinschaft erfasst unterstützte Chatereignisse jetzt direkt und hält einen kurzen Wiedergabeverlauf. Gilden- und Offiziersnachrichten bleiben dadurch vollständig, auch wenn Blizzard sie nicht an ein erkanntes Chatfenster leitet. Der synthetische Reiter gibt Rechtsklicks nicht mehr an einen nativen Reiter weiter und vermeidet so den Taint-Pfad der geschützten Chatfilter.",
    ["wn_402_quiet_startup"] = "Geändert — Erfolgsmeldungen beim Start von SkyRide, HideCastBar, UnitFrames, Boss-Frames und Namensplaketten füllen beim Login nicht mehr den Chat. Fehler sowie Sperr- und Kampfhinweise bleiben verfügbar.",
    ["wn_402_import_named_selective"] = "Neu — Der selektive Import funktioniert jetzt sowohl beim Erstellen eines benannten Profils als auch beim Aktualisieren der aktiven Konfiguration. Wähle die anzuwendenden Module aus; TomoMod speichert und aktiviert das Ergebnis anschließend unter dem gewünschten Profilnamen.",
    ["wn_402_import_destination_feedback"] = "Geändert — Der Importselektor zeigt jetzt an, ob sein Ziel die aktive Konfiguration oder ein neues benanntes Profil ist. Erfolgreiches Speichern und Fehler des Selektors werden klar und lokalisiert gemeldet, auch wenn eine Importzeichenfolge kein erkanntes Modul enthält.",
    ["wn_402_import_paste_absorber"] = "Behoben — Das Einfügen sehr langer Exportzeichenketten blockiert das Importfeld nicht mehr beim Darstellen Tausender Zeichen. Der vollständige Inhalt bleibt in einem leichten Lua-Puffer, während das Feld eine lokalisierte Zeichenzahl zeigt; kann der Client nicht alles liefern, wird sicher um ein erneutes Einfügen gebeten statt unbemerkt zu kürzen.",
    ["wn_402_import_decode_cache"] = "Geändert — Der selektive Import verwendet jetzt die bereits für die Vorschau dekodierten Daten und vermeidet einen zweiten Durchlauf aus Dekodierung, Dekomprimierung und Deserialisierung unmittelbar vor der Modulauswahl.",
    ["wn_402_import_layering"] = "Behoben — Das Fenster des selektiven Imports berechnet seine Anzeigeebene bei jedem Öffnen neu und hebt Hintergrund sowie Inhalt über das aktuelle TomoMod-Konfigurationsfenster. Ein wiederverwendeter Selektor kann nicht mehr dahinter verborgen bleiben.",
    ["wn_402_import_theme"] = "Geändert — Der Selektor verwendet jetzt das gemeinsame TomoMod-Design, Poppins-Schriften, eine vertiefte Inhaltsfläche, die schmale Bildlaufleiste, eigene Kontrollkästchen und passende Schaltflächen. Blizzard-Vorlagen und fest eingetragene Akzentfarben wurden aus der normalen Darstellung entfernt.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_402_astral_dragging"] = "Corregido — Al arrastrar un elemento en Astral Forge Studio ahora se mueve la propia vista previa, en lugar de convertir su marco de selección en un marco independiente anclado a la pantalla. El marco permanece unido al Studio cuando se mueve la ventana completa.",
    ["wn_402_astral_handles"] = "Cambio — Los marcos de selección ahora siguen automáticamente al elemento real de la vista previa cuando el Studio se mueve, cambia de tamaño o de escala. Los elementos pequeños siguen siendo fáciles de seleccionar sin alterar su geometría visible, y el ajuste y las guías de alineación continúan usando su posición real.",
    ["wn_402_astral_instances"] = "Novedad — Los elementos Forge instanciados ahora usan el mismo sistema de selección y arrastre que los elementos únicos. Las instancias de texto personalizado se pueden seleccionar, enmarcar y recolocar directamente en el lienzo, con la misma base preparada para futuras barras personalizadas.",
    ["wn_402_astral_frame_editor"] = "Novedad — Astral Forge Studio incorpora un editor de marco específico para Jugador, Objetivo y Placas de nombre. El botón Marco cambia del posicionamiento de elementos individuales a los ajustes del marco sin salir del Studio.",
    ["wn_402_astral_frame_controls"] = "Novedad — Ajusta directamente las dimensiones y la visualización principal: tamaños de las barras de salud, recursos, información y lanzamiento, tamaño del nombre, nombres, niveles y texto de salud, formato de salud, clasificación, barras de lanzamiento, colores de clase, absorciones y amenaza cuando el sujeto seleccionado lo permita.",
    ["wn_402_astral_frame_live"] = "Cambio — Los ajustes de marco usan las rutas habituales de perfil y actualización de TomoMod, por lo que la vista previa y los marcos del juego cambian al instante. Un restablecimiento específico recupera los valores predeterminados compatibles y la vista previa se puede actualizar por separado.",
    ["wn_402_astral_custom_bars"] = "Novedad — Crea hasta ocho barras personalizadas independientes en los marcos de Jugador y Objetivo, y hasta seis en las Placas de nombre. Cada barra es un elemento Forge normal que se puede seleccionar, arrastrar y anclar directamente en la vista previa.",
    ["wn_402_astral_bar_sources"] = "Novedad — Las barras personalizadas pueden seguir la Salud en directo, el Recurso en los marcos de unidad o mostrar un relleno decorativo estático. Ancho, alto, modo de color, color personalizado, opacidad del fondo y relleno inverso se configuran por separado para cada barra.",
    ["wn_402_astral_bar_runtime"] = "Cambio — Las barras de los marcos de unidad reciben directamente los valores protegidos de salud y recursos del juego. Las barras de las Placas de nombre siguen a su unidad y se limpian al liberar una placa reutilizada para evitar que el aspecto pase de una unidad a otra.",
    ["wn_402_astral_navigation"] = "Novedad — Marco, Elementos, Barras y Presets son ahora pestañas de navegación específicas sobre el lienzo, con un estado activo claro y selección sincronizada al cambiar de sujeto o elemento.",
    ["wn_402_astral_onboarding"] = "Novedad — Una guía inicial localizada de seis pasos presenta la selección de sujeto, la edición del marco, el movimiento por el lienzo, las barras personalizadas y los Presets. El progreso tiene versión y el botón Ayuda puede reiniciar la guía en cualquier momento.",
    ["wn_402_astral_localization"] = "Cambio — La ventana del Studio, la navegación, el selector de sujeto, la barra lateral, las acciones de actualizar y restablecer, la ayuda de colocación y el mensaje de selección están totalmente traducidos a los seis idiomas compatibles.",
    ["wn_402_bags_visuals"] = "Cambio — Bags V4 usa ahora un panel gris frío más claro y casillas hundidas. La calidad de los objetos se muestra con un tinte discreto de forma predeterminada, con las opciones Casilla teñida, Marco de color, Ambos y Ninguno; las casillas de la bolsa de componentes conservan su borde azul celeste.",
    ["wn_402_bags_rendering"] = "Corregido — Las casillas ocupadas dibujan ahora su propio icono y cantidad, en vez de depender de regiones internas de la plantilla de Blizzard que cambiaron en el cliente actual. Los objetos reales ya no parecen casillas vacías, mientras que los clics seguros, las descripciones y los tiempos de reutilización siguen siendo nativos.",
    ["wn_402_chat_community_filters"] = "Novedad — Haz clic derecho en la pestaña Comunidad para elegir por separado los mensajes privados, los susurros de Battle.net y los chats de hermandad y oficiales. El menú específico está traducido y actualiza inmediatamente la vista combinada.",
    ["wn_402_chat_community_capture"] = "Corregido — Comunidad captura ahora directamente los eventos de chat compatibles y conserva un breve historial para reproducirlo. Los mensajes de hermandad y oficiales permanecen completos aunque Blizzard no los envíe a una ventana de chat detectada. La pestaña sintética ya no reenvía el clic derecho a una pestaña nativa, evitando la ruta de contaminación de los filtros protegidos del chat.",
    ["wn_402_quiet_startup"] = "Cambio — Los avisos de inicialización correcta de SkyRide, HideCastBar, marcos de unidad, marcos de jefe y placas de nombre ya no llenan el chat al iniciar sesión. Los errores y avisos de bloqueo o combate siguen disponibles.",
    ["wn_402_import_named_selective"] = "Novedad — La importación selectiva funciona ahora tanto al crear un perfil con nombre como al actualizar la configuración activa. Elige los módulos que quieres aplicar y TomoMod guardará y activará el resultado con el nombre de perfil solicitado.",
    ["wn_402_import_destination_feedback"] = "Cambio — El selector de importación indica ahora si su destino es la configuración activa o un nuevo perfil con nombre. Los guardados correctos y los fallos del selector ofrecen mensajes claros y traducidos, incluso cuando una cadena de importación no contiene ningún módulo reconocido.",
    ["wn_402_import_paste_absorber"] = "Corregido — Pegar cadenas de exportación muy largas ya no bloquea el cuadro de importación al mostrar miles de caracteres. El contenido completo permanece en un búfer Lua ligero mientras el cuadro muestra un contador traducido; si el cliente no entrega todo el pegado, se solicita repetirlo de forma segura en lugar de truncarlo sin avisar.",
    ["wn_402_import_decode_cache"] = "Cambio — La importación selectiva reutiliza ahora los datos ya decodificados para la vista previa, evitando una segunda decodificación, descompresión y deserialización justo antes de seleccionar los módulos.",
    ["wn_402_import_layering"] = "Corregido — El panel de importación selectiva recalcula su nivel de visualización cada vez que se abre y eleva tanto el fondo como el contenido sobre la ventana de configuración actual de TomoMod, por lo que un selector reutilizado ya no puede quedar oculto detrás.",
    ["wn_402_import_theme"] = "Cambio — El selector usa ahora el tema compartido de TomoMod, las fuentes Poppins, una superficie de contenido hundida, la barra de desplazamiento fina, casillas personalizadas y botones temáticos. Las plantillas de Blizzard y los colores de acento fijos se han eliminado de su presentación normal.",
})

TomoMod_RegisterLocale("itIT", {
    ["wn_402_astral_dragging"] = "Correzione — Trascinare un elemento in Astral Forge Studio ora sposta direttamente l'anteprima, invece di trasformare il riquadro di selezione in un frame indipendente ancorato allo schermo. Il riquadro resta collegato allo Studio quando viene spostata l'intera finestra.",
    ["wn_402_astral_handles"] = "Modifica — I riquadri di selezione ora seguono automaticamente l'elemento reale dell'anteprima quando lo Studio viene spostato, ridimensionato o riscalato. Gli elementi piccoli restano facili da selezionare senza alterarne la geometria visibile, mentre l'aggancio e le guide di allineamento continuano a usare la loro posizione reale.",
    ["wn_402_astral_instances"] = "Novità — Gli elementi Forge istanziati ora usano lo stesso sistema di selezione e trascinamento degli elementi singoli. Le istanze di testo personalizzato possono essere selezionate, evidenziate e riposizionate direttamente sulla tela, con la stessa base pronta per future barre personalizzate.",
    ["wn_402_astral_frame_editor"] = "Novità — Astral Forge Studio introduce un editor del riquadro dedicato a Giocatore, Bersaglio e Nameplate. Il pulsante Riquadro passa dal posizionamento dei singoli elementi alle impostazioni del riquadro senza uscire dallo Studio.",
    ["wn_402_astral_frame_controls"] = "Novità — Regola direttamente dimensioni e visualizzazione principale: misure delle barre salute, risorsa, informazioni e lancio, dimensione del nome, nomi, livelli e testo della salute, formato della salute, classificazione, barre di lancio, colori di classe, assorbimenti e minaccia quando supportati dal soggetto selezionato.",
    ["wn_402_astral_frame_live"] = "Modifica — Le impostazioni del riquadro usano i normali percorsi di profilo e aggiornamento di TomoMod, modificando immediatamente anteprima e riquadri di gioco. Un ripristino dedicato recupera i valori predefiniti supportati, mentre l'anteprima può essere aggiornata separatamente.",
    ["wn_402_astral_custom_bars"] = "Novità — Crea fino a otto barre personalizzate indipendenti sui riquadri Giocatore e Bersaglio e fino a sei sulle Nameplate. Ogni barra è un normale elemento Forge che può essere selezionato, trascinato e ancorato direttamente nell'anteprima.",
    ["wn_402_astral_bar_sources"] = "Novità — Le barre personalizzate possono seguire la Salute in tempo reale, la Risorsa sui riquadri unità o mostrare un riempimento decorativo statico. Larghezza, altezza, modalità colore, colore personale, opacità dello sfondo e riempimento inverso si configurano separatamente per ogni barra.",
    ["wn_402_astral_bar_runtime"] = "Modifica — Le barre dei riquadri unità ricevono direttamente i valori protetti di salute e risorsa forniti dal gioco. Le barre delle Nameplate seguono la propria unità e vengono rimosse quando una targa riutilizzata viene liberata, evitando trasferimenti visivi tra unità.",
    ["wn_402_astral_navigation"] = "Novità — Riquadro, Elementi, Barre e Preset sono ora schede di navigazione dedicate sopra il canvas, con uno stato attivo chiaro e selezione sincronizzata quando cambia il soggetto o l'elemento.",
    ["wn_402_astral_onboarding"] = "Novità — Una guida iniziale localizzata in sei passaggi presenta selezione del soggetto, modifica del riquadro, movimento sul canvas, barre personalizzate e Preset. I progressi sono versionati e il pulsante Aiuto può riavviare la guida in qualsiasi momento.",
    ["wn_402_astral_localization"] = "Modifica — Finestra dello Studio, navigazione, selettore del soggetto, barra laterale, azioni di aggiornamento e ripristino, suggerimento di posizionamento e guida alla selezione sono ora tradotti integralmente nelle sei lingue supportate.",
    ["wn_402_bags_visuals"] = "Modifica — Bags V4 usa ora un pannello grigio freddo più chiaro e slot incassati. La qualità degli oggetti viene mostrata con una tinta discreta per impostazione predefinita, con le opzioni Slot colorato, Cornice colorata, Entrambi e Nessuno; gli slot della borsa dei reagenti mantengono il bordo azzurro.",
    ["wn_402_bags_rendering"] = "Correzione — Gli slot occupati disegnano ora la propria icona e quantità invece di dipendere dalle regioni interne del modello Blizzard modificate nel client attuale. Gli oggetti reali non sembrano più slot vuoti, mentre clic protetti, tooltip e tempi di recupero restano nativi.",
    ["wn_402_chat_community_filters"] = "Novità — Fai clic destro sulla scheda Comunità per scegliere separatamente messaggi privati, sussurri Battle.net e chat di gilda e ufficiali. Il menu dedicato è localizzato e aggiorna immediatamente la vista combinata.",
    ["wn_402_chat_community_capture"] = "Correzione — Comunità acquisisce ora direttamente gli eventi chat supportati e conserva una breve cronologia da riprodurre. I messaggi di gilda e ufficiali restano completi anche se Blizzard non li inoltra a una finestra chat rilevata. La scheda sintetica non inoltra più il clic destro a una scheda nativa, evitando il percorso di contaminazione dei filtri chat protetti.",
    ["wn_402_quiet_startup"] = "Modifica — Le notifiche di inizializzazione riuscita di SkyRide, HideCastBar, UnitFrame, frame dei boss e Nameplate non riempiono più la chat all'accesso. Errori e avvisi di blocco o combattimento restano disponibili.",
    ["wn_402_import_named_selective"] = "Novità — L'importazione selettiva funziona ora sia durante la creazione di un profilo con nome sia durante l'aggiornamento della configurazione attiva. Scegli i moduli da applicare e TomoMod salverà e attiverà il risultato con il nome del profilo richiesto.",
    ["wn_402_import_destination_feedback"] = "Modifica — Il selettore di importazione mostra ora se la destinazione è la configurazione attiva o un nuovo profilo con nome. I salvataggi riusciti e gli errori del selettore forniscono messaggi chiari e localizzati, anche quando una stringa di importazione non contiene moduli riconosciuti.",
    ["wn_402_import_paste_absorber"] = "Correzione — Incollare stringhe di esportazione molto lunghe non blocca più la casella di importazione durante la visualizzazione di migliaia di caratteri. Il contenuto completo resta in un leggero buffer Lua mentre la casella mostra un conteggio localizzato; se il client non consegna tutto il testo, viene richiesta una nuova incollatura sicura invece di troncarlo senza avviso.",
    ["wn_402_import_decode_cache"] = "Modifica — L'importazione selettiva riutilizza ora i dati già decodificati per l'anteprima, evitando un secondo passaggio di decodifica, decompressione e deserializzazione subito prima della scelta dei moduli.",
    ["wn_402_import_layering"] = "Correzione — Il pannello di importazione selettiva ricalcola il proprio livello a ogni apertura e solleva sfondo e contenuto sopra la finestra di configurazione TomoMod corrente, quindi un selettore riutilizzato non può più restare nascosto dietro di essa.",
    ["wn_402_import_theme"] = "Modifica — Il selettore usa ora il tema condiviso di TomoMod, i font Poppins, una superficie dei contenuti incassata, la barra di scorrimento sottile, caselle personalizzate e pulsanti coordinati. I modelli Blizzard e i colori d'accento fissi sono stati rimossi dalla presentazione normale.",
})

TomoMod_RegisterLocale("ptBR", {
    ["wn_402_astral_dragging"] = "Correção — Arrastar um elemento no Astral Forge Studio agora move a própria prévia, em vez de transformar sua moldura de seleção em um quadro independente ancorado à tela. A moldura permanece ligada ao Studio quando a janela inteira é movida.",
    ["wn_402_astral_handles"] = "Alteração — As molduras de seleção agora acompanham automaticamente o elemento real da prévia quando o Studio é movido, redimensionado ou reescalado. Elementos pequenos continuam fáceis de selecionar sem alterar sua geometria visível, e o encaixe e as guias de alinhamento continuam usando sua posição real.",
    ["wn_402_astral_instances"] = "Novidade — Elementos Forge instanciados agora usam o mesmo sistema de seleção e arraste que os elementos únicos. Instâncias de texto personalizado podem ser selecionadas, contornadas e reposicionadas diretamente na tela de edição, com a mesma base pronta para futuras barras personalizadas.",
    ["wn_402_astral_frame_editor"] = "Novidade — O Astral Forge Studio ganha um editor de quadro dedicado a Jogador, Alvo e Placas de nome. O botão Quadro alterna do posicionamento de elementos individuais para os ajustes do quadro sem sair do Studio.",
    ["wn_402_astral_frame_controls"] = "Novidade — Ajuste diretamente as dimensões e a exibição principal: tamanhos das barras de vida, recurso, informações e lançamento, tamanho do nome, nomes, níveis e texto de vida, formato de vida, classificação, barras de lançamento, cores de classe, absorções e ameaça quando compatíveis com o alvo selecionado.",
    ["wn_402_astral_frame_live"] = "Alteração — Os ajustes de quadro usam os caminhos normais de perfil e atualização do TomoMod, atualizando imediatamente a prévia e os quadros do jogo. Uma redefinição dedicada restaura os campos compatíveis aos valores padrão, e a prévia ainda pode ser atualizada separadamente.",
    ["wn_402_astral_custom_bars"] = "Novidade — Crie até oito barras personalizadas independentes nos quadros de Jogador e Alvo e até seis nas Placas de nome. Cada barra é um elemento Forge normal que pode ser selecionado, arrastado e ancorado diretamente na prévia.",
    ["wn_402_astral_bar_sources"] = "Novidade — As barras personalizadas podem acompanhar a Vida em tempo real, o Recurso nos quadros de unidade ou exibir um preenchimento decorativo estático. Largura, altura, modo de cor, cor personalizada, opacidade do fundo e preenchimento invertido são configurados separadamente para cada barra.",
    ["wn_402_astral_bar_runtime"] = "Alteração — As barras dos quadros de unidade recebem diretamente os valores protegidos de vida e recurso fornecidos pelo jogo. As barras das Placas de nome acompanham sua unidade e são limpas quando uma placa reutilizada é liberada, evitando que o visual passe entre unidades.",
    ["wn_402_astral_navigation"] = "Novidade — Quadro, Elementos, Barras e Predefinições agora são abas de navegação próprias acima da tela de edição, com estado ativo claro e seleção sincronizada ao trocar de assunto ou elemento.",
    ["wn_402_astral_onboarding"] = "Novidade — Um guia inicial localizado em seis etapas apresenta a seleção de assunto, edição do quadro, movimento na tela, barras personalizadas e Predefinições. O progresso é versionado e o botão Ajuda pode reiniciar o guia a qualquer momento.",
    ["wn_402_astral_localization"] = "Alteração — A janela do Studio, navegação, seletor de assunto, barra lateral, ações de atualizar e redefinir, dica de posicionamento e orientação de seleção agora estão totalmente traduzidos nos seis idiomas compatíveis.",
    ["wn_402_bags_visuals"] = "Alteração — Bags V4 usa agora um painel cinza frio mais claro e espaços rebaixados. A qualidade dos itens aparece com uma tonalidade discreta por padrão, com as opções Espaço colorido, Moldura colorida, Ambos e Nenhum; os espaços da bolsa de reagentes mantêm a borda azul-clara.",
    ["wn_402_bags_rendering"] = "Correção — Espaços ocupados agora desenham seu próprio ícone e quantidade em vez de depender de regiões internas do modelo da Blizzard alteradas no cliente atual. Itens reais não parecem mais espaços vazios, enquanto cliques protegidos, dicas e recargas continuam nativos.",
    ["wn_402_chat_community_filters"] = "Novidade — Clique com o botão direito na aba Comunidade para escolher separadamente mensagens privadas, sussurros do Battle.net e bate-papos de guilda e oficiais. O menu dedicado é localizado e atualiza imediatamente a visualização combinada.",
    ["wn_402_chat_community_capture"] = "Correção — Comunidade agora captura diretamente os eventos de chat compatíveis e mantém um breve histórico para reprodução. As mensagens de guilda e oficiais permanecem completas mesmo quando a Blizzard não as envia a uma janela de chat detectada. A aba sintética não repassa mais o clique direito a uma aba nativa, evitando o caminho de taint dos filtros protegidos do chat.",
    ["wn_402_quiet_startup"] = "Alteração — As mensagens de inicialização bem-sucedida de SkyRide, HideCastBar, quadros de unidade, quadros de chefes e placas de nome não enchem mais o chat ao entrar. Erros e avisos de bloqueio ou combate continuam disponíveis.",
    ["wn_402_import_named_selective"] = "Novidade — A importação seletiva agora funciona tanto ao criar um perfil nomeado quanto ao atualizar a configuração ativa. Escolha os módulos que deseja aplicar e o TomoMod salvará e ativará o resultado com o nome de perfil solicitado.",
    ["wn_402_import_destination_feedback"] = "Alteração — O seletor de importação agora mostra se o destino é a configuração ativa ou um novo perfil nomeado. Salvamentos concluídos e falhas do seletor fornecem mensagens claras e localizadas, inclusive quando uma string de importação não contém nenhum módulo reconhecido.",
    ["wn_402_import_paste_absorber"] = "Correção — Colar strings de exportação muito longas não trava mais a caixa de importação ao exibir milhares de caracteres. O conteúdo completo fica em um buffer Lua leve enquanto a caixa mostra uma contagem localizada; se o cliente não entregar toda a colagem, uma nova tentativa segura é solicitada em vez de truncar os dados silenciosamente.",
    ["wn_402_import_decode_cache"] = "Alteração — A importação seletiva agora reutiliza os dados já decodificados para a prévia, evitando uma segunda etapa de decodificação, descompressão e desserialização imediatamente antes da seleção dos módulos.",
    ["wn_402_import_layering"] = "Correção — O painel de importação seletiva recalcula seu nível de exibição sempre que abre e eleva o fundo e o conteúdo acima da janela de configuração atual do TomoMod, impedindo que um seletor reutilizado permaneça oculto atrás dela.",
    ["wn_402_import_theme"] = "Alteração — O seletor agora usa o tema compartilhado do TomoMod, fontes Poppins, uma superfície de conteúdo rebaixada, a barra de rolagem fina, caixas personalizadas e botões temáticos. Modelos da Blizzard e cores de destaque fixas foram removidos da apresentação normal.",
})
